fun allowsNullValueFalseWhenAnotherDiscriminatorIsValid() {
        assertEquals(
            "I",
            ConstantAtArgsParser.parse(listOf("nullValue=false", "intValue=1")),
        )
    }

fun allowsRepeatedSameDiscriminator() {
        assertEquals(
            "I",
