                constantCandidate(ConstantValue.IntValue(42), instructionOccurrenceIndex = 6),
            ),
        )

        assertEquals(
            setOf(3, 6),
            resolver.resolve(
                owner = owner,
                targetMethod = targetMethod,
                site = site(
                    atValue = "CONSTANT",
                    atArgs = listOf("intValue=42"),
                ),
            ),
        )
        assertEquals(
            setOf(1),
            resolver.resolve(
                owner = owner,
                targetMethod = targetMethod,
                site = site(
                    atValue = "CONSTANT",
                    atArgs = listOf("intValue=0"),
                ),
            ),
        )
        assertEquals(
            emptySet(),
            resolver.resolve(
                owner = owner,
                targetMethod = targetMethod,
                site = site(
                    atValue = "CONSTANT",
                    atArgs = listOf("intValue=99"),
                ),
            ),
        )
    }

