fun companionHandlerRetainsLocalShareAndCancellableSugar() {
        val source = """
            import org.spongepowered.asm.mixin.injection.Inject as On
            import org.spongepowered.asm.mixin.injection.At as Point
            import com.llamalad7.mixinextras.sugar.Local as Capture
            import com.llamalad7.mixinextras.sugar.Share as Shared
            import com.llamalad7.mixinextras.sugar.Cancellable as Cancel
            class Patch {
                companion object {
                    @On(method = ["staticLocal"], at = [Point("RETURN")])
                    fun capture(@Capture(name = ["first", "second"], type = Int::class) value: Int,
                                @Shared("bonus") bonus: LocalIntRef,
                                @Cancel cir: CallbackInfoReturnable<Int>) {}
                }
                fun instance() {}
            }
        """.trimIndent()

        val handler = assertNotNull(HandlerSignatureService.findSugarHandlerAnnotationSites(source).single().handlerMethod)

        assertTrue(handler.isStatic)
        assertEquals(setOf("first", "second"), (handler.parameters[0].sugarSpec as HandlerParameterSugarSpec.Local).names)
        assertEquals("Int", (handler.parameters[0].sugarSpec as HandlerParameterSugarSpec.Local).typeClassName)
        assertEquals("bonus", (handler.parameters[1].sugarSpec as HandlerParameterSugarSpec.Share).value)
        assertEquals(HandlerParameterSugarSpec.Cancellable, handler.parameters[2].sugarSpec)
        assertFalse(assertNotNull(HandlerSignatureService.parseHandlerMethod(source, source.indexOf("fun instance"))).isStatic)
    }

fun companionStaticDetectionStopsAtNestedClassesAndObjects() {
        val source = """
            import kotlin.Unit
            class Patch {
                companion object Factory {
                    fun firstStatic() {}
                    class Nested {
                        fun nestedInstance() {}
                        companion object { fun nestedStatic() {} }
                    }
                    object Other { fun objectInstance() {} }
                    fun afterNestedStatic() {}
                }
                fun outerInstance() {}
            }
        """.trimIndent()
        for ((name, isStatic) in mapOf(
            "firstStatic" to true, "nestedInstance" to false, "nestedStatic" to true,
            "objectInstance" to false, "afterNestedStatic" to true, "outerInstance" to false,
        )) {
            val offset = source.indexOf("fun $name")
            assertEquals(isStatic, HandlerSignatureService.isKotlinCompanionMember(source, offset), name)
            assertEquals(isStatic, assertNotNull(HandlerSignatureService.parseHandlerMethod(source, offset)).isStatic, name)
        }
    }

