fun inferredReturnDoesNotInventAnErrorButExplicitWrongReturnAndInvalidParametersStillDo() {
        fun source(handler: String) = """
            import com.llamalad7.mixinextras.injector.ModifyReturnValue
            import org.spongepowered.asm.mixin.injection.At
            class Patch {
                @ModifyReturnValue(method = ["compute()I"], at = [At("RETURN")])
                $handler
            }
        """.trimIndent()

        assertTrue(validationIssues(source("fun result(original: Int) = original * 2")).isEmpty())
        assertTrue(validationIssues(source("fun result(original: Int): String = \"bad\""))
            .any { it.code == MixinExtrasDiagnosticCodes.WRONG_RETURN_TYPE })
        val invalidParameter = validationIssues(source("fun result(original: String) = original"))
        assertTrue(invalidParameter.any { it.code == MixinExtrasDiagnosticCodes.WRONG_ORIGINAL_VALUE_TYPE })
        assertFalse(invalidParameter.any { it.code == MixinExtrasDiagnosticCodes.WRONG_RETURN_TYPE })
    }

fun kotlinConstantArraysAndExpandedConditionsKeepOfficialIdentities() {
        val source = """
            import org.spongepowered.asm.mixin.injection.ModifyConstant
            import org.spongepowered.asm.mixin.injection.Constant as Literal
            import org.spongepowered.asm.mixin.injection.Constant.Condition.LESS_THAN_ZERO as Below
            class Patch {
                @ModifyConstant(method = ["compute()I"], slice = [], constant = [
                    Literal(intValue = 0, expandZeroConditions = [Below, Literal.Condition.GREATER_THAN_ZERO]),
                    Literal(intValue = 1)
                ])
                fun constant(original: Int): Int { return original }
            }
        """.trimIndent()
        val sites = HandlerSignatureService.findSugarHandlerAnnotationSites(source)
        assertEquals(listOf(listOf("intValue=0"), listOf("intValue=1")), sites.map { it.atArgs })
        assertEquals(setOf(Opcodes.IFLT, Opcodes.IFGE, Opcodes.IFGT, Opcodes.IFLE), sites.first().expandZeroConditions)
        assertTrue(sites.all { service.validateHandler(source, it, targets, enriched(it, source)).isEmpty() })
        for (lookalike in listOf(
            source.replace("import org.spongepowered.asm.mixin.injection.Constant as Literal", "import impostor.Constant as Literal"),
            source.replace("import org.spongepowered.asm.mixin.injection.Constant.Condition.LESS_THAN_ZERO as Below", "import impostor.Condition.LESS_THAN_ZERO as Below"),
        )) {
            val site = HandlerSignatureService.findSugarHandlerAnnotationSites(lookalike).single()
            assertNull(site.atValue)
            assertNull(service.expectedSignature(lookalike, site, targets))
        }
    }

fun operationGenericUsesJvmTypesForAliasesQualifiedNamesAndNullableBoxes() {
        fun source(generic: String) = """
            import com.llamalad7.mixinextras.injector.wrapmethod.WrapMethod
            import com.llamalad7.mixinextras.injector.wrapoperation.Operation as Op
            import kotlin.Int as Count
            class Patch {
                @WrapMethod(method = ["compute()I"])
                fun wrap(original: Op<$generic>): Int { return 0 }
            }
        """.trimIndent()

        for (generic in listOf("Count", "kotlin.Int", "Int?", "java.lang.Integer")) {
            val text = source(generic)
            val handler = enriched(HandlerSignatureService.findAnnotationSites(text).single(), text)
            assertEquals("Ljava/lang/Integer;", handler.parameters.single().operationGenericDescriptor, generic)
            assertTrue(validationIssues(text).isEmpty(), generic)
        }
        for (generic in listOf("String", "Missing")) {
            assertTrue(validationIssues(source(generic)).any { it.code == MixinExtrasDiagnosticCodes.WRONG_OPERATION_GENERIC }, generic)
        }
        val text = source("Count")
        val site = HandlerSignatureService.findAnnotationSites(text).single()
        val expected = assertNotNull(service.expectedSignature(text, site, targets)).parameters.single()
        val actual = enriched(site, text).parameters.single()
        assertTrue(service.parameterTypeMatches(expected, actual.copy(operationGenericName = "Integer", operationGenericDescriptor = null)))
        assertFalse(service.parameterTypeMatches(expected, actual.copy(operationGenericName = "I", operationGenericDescriptor = null)))
    }

